import json
with open('/work/output/artifacts/skill-flow-bindings-no-duplicates/BindingsRegression/flow_files/BindingsRegression.flow') as f:
    flow = json.load(f)

bindings = flow.get('bindings', [])
print('=== bindings count:', len(bindings))
for b in bindings:
    print(' ', b.get('id'), '-', b.get('name'), '-', b.get('resourceKey', '(empty)'), '-', b.get('propertyAttribute'))

print()
print('=== connector node inputs.detail keys:')
for n in flow.get('nodes', []):
    if 'connector' in n.get('type',''):
        detail = n.get('inputs',{}).get('detail',{})
        print('  node:', n['id'])
        for k,v in detail.items():
            if k != 'configuration':
                print('   ', k, ':', v)
            else:
                print('   ', k, ': <jsonString blob>')
"
